// ================================================================
// FIND DHCPACK BY MAC
// Tim IP thuc te duoc pfSense xac nhan cho MAC vua APPROVE
// ================================================================

const log =
  $('Extract DHCP (verify)').first()?.json?.data || '';

const device =
  $('Resolve Pending Device').first()?.json || {};

const mac = String(device.mac || '')
  .trim()
  .toLowerCase();

const approvalStartedAt =
  Date.parse(device.approval_started_at || '');

if (!/^[0-9a-f]{2}(?::[0-9a-f]{2}){5}$/i.test(mac)) {
  throw new Error(`MAC không hợp lệ: "${mac}"`);
}

const escapedMac = mac.replace(
  /[.*+?^${}()|[\]\\]/g,
  '\\$&'
);

// Vi du:
// DHCPACK on 192.168.12.200 to 00:0c:29:49:fb:b4 (DESKTOP-D24DCNT) via em3
const ackRegex = new RegExp(
  '\\bDHCPACK\\s+on\\s+' +
  '(\\d{1,3}(?:\\.\\d{1,3}){3})' +
  '\\s+to\\s+' +
  escapedMac +
  '(?:\\s+\\(([^)]+)\\))?',
  'i'
);

const lines = log.split(/\r?\n/);

let assignedIp = '';
let hostname = String(device.hostname || '').trim();
let ackLine = '';
let ackTimestamp = '';

// Doc tu cuoi log len de lay DHCPACK moi nhat
for (let index = lines.length - 1; index >= 0; index--) {
  const line = lines[index].trim();

  if (!line) continue;

  const match = line.match(ackRegex);
  if (!match) continue;

  // Neu log co timestamp ISO o dau dong:
  // 2026-07-26T07:07:03.947623+00:00 ...
  const timestampMatch = line.match(
    /^(\d{4}-\d{2}-\d{2}T\S+)/
  );

  if (timestampMatch && Number.isFinite(approvalStartedAt)) {
    const lineTime = Date.parse(timestampMatch[1]);

    // Bo qua DHCPACK cu truoc luc admin bam APPROVE
    if (
      Number.isFinite(lineTime) &&
      lineTime < approvalStartedAt - 2000
    ) {
      continue;
    }

    ackTimestamp = timestampMatch[1];
  }

  assignedIp = String(match[1] || '').trim();

  if (match[2]) {
    hostname = String(match[2]).trim();
  }

  ackLine = line;
  break;
}

// Chua thay DHCPACK moi
if (!assignedIp) {
  return [
    {
      json: {
        ...device,

        verified: false,
        mac,
        hostname,

        telegram_text:
          '⏳ ĐÃ APPROVE THIẾT BỊ\n' +
          'MAC: ' + mac + '\n' +
          'Hostname: ' + (hostname || '') + '\n' +
          'Admin: ' + (device.by || '') + '\n\n' +
          'Ansible đã xử lý nhưng chưa tìm thấy DHCPACK mới từ pfSense.',
      },
    },
  ];
}

// Da thay DHCPACK
return [
  {
    json: {
      ...device,

      verified: true,

      mac,
      ip: assignedIp,
      hostname,

      dhcp_ack_line: ackLine,
      dhcp_ack_timestamp: ackTimestamp,

      telegram_text:
        '✅ APPROVED\n' +
        'MAC: ' + mac + '\n' +
        'IP: ' + assignedIp + '\n' +
        'Hostname: ' + (hostname || '') + '\n' +
        'Admin: ' + (device.by || ''),
    },
  },
];
